css:
@keyframes fade-in-up {
            from { opacity: 0; transform: translateY(20px); }
            to { opacity: 1; transform: translateY(0); }
        }
        .animate-fade-in-up { animation: fade-in-up 0.5s ease-out forwards; }
        .step-progress { transition: width 0.3s ease-in-out; }
        .resource-card { transition: transform 0.2s; }
        .resource-card:hover { transform: translateY(-4px); }
        .step-button.active { background-color: #EFF6FF; color: #2563EB; }
        .quiz-option.selected { border-color: #2563EB; background-color: #EFF6FF; }
        .quiz-option.correct { border-color: #16A34A; background-color: #F0FDF4; }
        .quiz-option.incorrect { background-color: #fff5f5; border-color: #e53e3e; }

        #modeLearnBtn.active { background-color: #EFF6FF; color: #2563EB; }
        #modeAIBtn { position: relative; cursor: not-allowed; opacity: 0.7; }

        .sidebar-overlay {
            display: none;
            position: fixed;
            top: 0; left: 0; right: 0; bottom: 0;
            background: rgba(0,0,0,0.5);
            z-index: 40;
        }
        .sidebar-overlay.show { display: block; }

        .simulation-container {
            position: relative;
            width: 100%;
            height: 500px;
            overflow: hidden;
            border-radius: 8px;
            background: #f9fafb;
        }
        .simulation-container iframe {
            width: 100%;
            height: 100%;
            border: none;
        }

        .video-container {
            position: relative;
            width: 100%;
            padding-bottom: 56.25%;
            height: 0;
            overflow: hidden;
            border-radius: 8px;
            background: #f9fafb;
        }
        .video-container iframe {
            position: absolute;
            top: 0; left: 0;
            width: 100%;
            height: 100%;
            border: none;
        }

        @media (max-width: 768px) {
            .desktop-sidebar { display: none; }
            .mobile-sidebar {
                position: fixed;
                top: 0; left: -280px;
                width: 280px;
                height: 100%;
                background: white;
                z-index: 50;
                transition: left 0.3s ease;
                overflow-y: auto;
                box-shadow: 2px 0 10px rgba(0,0,0,0.1);
            }
            .mobile-sidebar.show { left: 0; }
            .simulation-container { height: 300px; }
        }

        .section-card {
            background: white;
            border-radius: 12px;
            padding: 1.5rem;
            margin-bottom: 1.5rem;
            box-shadow: 0 2px 8px rgba(0,0,0,0.05);
            border: 1px solid #e5e7eb;
        }

        .intro-text {
            background: linear-gradient(135deg, #ecfdf5 0%, #d1fae5 100%);
            border-left: 4px solid #10b981;
            padding: 1rem 1.25rem;
            border-radius: 0 8px 8px 0;
            margin-bottom: 1.5rem;
        }
        .intro-text p {
            color: #065f46;
            font-size: 1rem;
            line-height: 1.6;
        }

        .formula-box {
            background: linear-gradient(135deg, #f0f9ff 0%, #e0f2fe 100%);
            border: 2px solid #3b82f6;
            border-radius: 12px;
            padding: 1.5rem;
            text-align: center;
            font-size: 1.5rem;
            font-weight: 600;
            color: #1e40af;
        }

        .coming-soon-badge {
            background: linear-gradient(135deg, #f59e0b, #d97706);
            color: white;
            font-size: 10px;
            padding: 2px 8px;
            border-radius: 9999px;
            margin-left: 8px;
            text-transform: uppercase;
            font-weight: 600;
            animation: pulse 2s infinite;
            white-space: nowrap;
            display: inline-block;
        }
        @keyframes pulse {
            0%, 100% { opacity: 1; }
            50% { opacity: 0.7; }
        }

        .click-hint {
            display: flex;
            align-items: center;
            justify-content: center;
            gap: 6px;
            color: #9ca3af;
            font-size: 0.875rem;
            font-weight: 400;
            cursor: pointer;
            margin-top: 16px;
        }

        .law-card {
            background: linear-gradient(135deg, #fef3c7 0%, #fde68a 100%);
            border: 2px solid #f59e0b;
            border-radius: 12px;
            padding: 1.5rem;
            margin-bottom: 1rem;
        }
        .law-card h4 {
            color: #92400e;
            font-weight: 700;
        }
